1	export type Cell = [x: number, y: number];
2	
3	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighboursOf = ([x, y]: Cell): Cell[] =>
6	  [-1, 0, 1].flatMap((dx) =>
7	    [-1, 0, 1]
8	      .filter((dy) => dx !== 0 || dy !== 0)
9	      .map((dy): Cell => [x + dx, y + dy]),
10	  );
11	
12	const countLivingNeighboursPerCell = (livingCells: Cell[]): Map<string, [Cell, number]> => {
13	  const counts = new Map<string, [Cell, number]>();
14	  for (const living of livingCells) {
15	    for (const neighbour of neighboursOf(living)) {
16	      const key = keyOf(neighbour);
17	      const [, count] = counts.get(key) ?? [neighbour, 0];
18	      counts.set(key, [neighbour, count + 1]);
19	    }
20	  }
21	  return counts;
22	};
23	
24	export function nextGeneration(livingCells: Cell[]): Cell[] {
25	  const livingKeys = new Set(livingCells.map(keyOf));
26	
27	  return [...countLivingNeighboursPerCell(livingCells)]
28	    .filter(([key, [, livingNeighbours]]) =>
29	      livingNeighbours === 3 || (livingNeighbours === 2 && livingKeys.has(key)),
30	    )
31	    .map(([, [cell]]) => cell);
32	}
